  "alert-dialog:Destructive": "function AlertDestructive() {\n          const [status, setStatus] = useState(\"\")\n          return (\n            <div className=\"flex flex-col items-center gap-2\">\n              <AlertDialog>\n                <AlertDialogTrigger asChild>\n                  <Button variant=\"destructive\">Delete project</Button>\n                </AlertDialogTrigger>\n                <AlertDialogContent>\n                  <AlertDialogHeader>\n                    <AlertDialogTitle>Delete project?</AlertDialogTitle>\n                    <AlertDialogDescription>\n                      This will permanently delete the project and all associated\n                      data.\n                    </AlertDialogDescription>\n                  </AlertDialogHeader>\n                  <AlertDialogFooter>\n                    <AlertDialogCancel>Cancel</AlertDialogCancel>\n                    <AlertDialogAction\n                      variant=\"destructive\"\n                      onClick={() => setStatus(\"Project deleted (simulated)\")}\n                    >\n                      Delete\n                    </AlertDialogAction>\n                  </AlertDialogFooter>\n                </AlertDialogContent>\n              </AlertDialog>\n              {status && (\n                <p className=\"text-sm text-muted-foreground\">{status}</p>\n              )}\n            </div>\n          )\n        }",
  "alert-dialog:Media": "const Demo = () => (\n          <AlertDialog>\n            <AlertDialogTrigger asChild>\n              <Button variant=\"outline\">With media</Button>\n            </AlertDialogTrigger>\n            <AlertDialogContent>\n              <AlertDialogHeader>\n                <AlertDialogMedia>\n                  <MailIcon className=\"size-6\" />\n                </AlertDialogMedia>\n                <AlertDialogTitle>Check your email</AlertDialogTitle>\n                <AlertDialogDescription>\n                  We sent a verification link to your email address.\n                </AlertDialogDescription>\n              </AlertDialogHeader>\n              <AlertDialogFooter>\n                <AlertDialogCancel>Dismiss</AlertDialogCancel>\n                <AlertDialogAction>Open email</AlertDialogAction>\n              </AlertDialogFooter>\n            </AlertDialogContent>\n          </AlertDialog>\n        )",
  "alert-dialog:Small": "const Demo = () => (\n          <AlertDialog>\n            <AlertDialogTrigger asChild>\n              <Button variant=\"outline\">Small dialog</Button>\n            </AlertDialogTrigger>\n            <AlertDialogContent size=\"sm\">\n              <AlertDialogHeader>\n                <AlertDialogTitle>Delete this item?</AlertDialogTitle>\n                <AlertDialogDescription>\n                  This action cannot be undone.\n                </AlertDialogDescription>\n              </AlertDialogHeader>\n              <AlertDialogFooter>\n                <AlertDialogCancel>Cancel</AlertDialogCancel>\n                <AlertDialogAction>Delete</AlertDialogAction>\n              </AlertDialogFooter>\n            </AlertDialogContent>\n          </AlertDialog>\n        )",
  "alert-dialog:Small with media": "const Demo = () => (\n          <AlertDialog>\n            <AlertDialogTrigger asChild>\n              <Button variant=\"outline\">Small + media</Button>\n            </AlertDialogTrigger>\n            <AlertDialogContent size=\"sm\">\n              <AlertDialogHeader>\n                <AlertDialogMedia>\n                  <ImageIcon className=\"size-6\" />\n                </AlertDialogMedia>\n                <AlertDialogTitle>Upload complete</AlertDialogTitle>\n                <AlertDialogDescription>\n                  Your image has been uploaded successfully.\n                </AlertDialogDescription>\n              </AlertDialogHeader>\n              <AlertDialogFooter>\n                <AlertDialogCancel>Close</AlertDialogCancel>\n                <AlertDialogAction>View</AlertDialogAction>\n              </AlertDialogFooter>\n            </AlertDialogContent>\n          </AlertDialog>\n        )",
  "alert:Action": "const Demo = () => {\n          const [dismissed, setDismissed] = useState(false)\n          if (dismissed) {\n            return (\n              <div className=\"flex w-full max-w-md items-center gap-3\">\n                <CheckCircleIcon className=\"size-4 text-muted-foreground\" />\n                <span className=\"text-sm text-muted-foreground\">Alert dismissed</span>\n                <Button size=\"xs\" variant=\"outline\" onClick={() => setDismissed(false)}>\n                  Show again\n                </Button>\n              </div>\n            )\n          }\n          return (\n            <Alert className=\"w-full max-w-md\">\n              <InfoIcon />\n              <AlertTitle>New update available</AlertTitle>\n              <AlertDescription>\n                A new version is ready to install. Restart to apply changes.\n              </AlertDescription>\n              <AlertAction>\n                <Button size=\"xs\" variant=\"outline\" onClick={() => setDismissed(true)}>\n                  Dismiss\n                </Button>\n              </AlertAction>\n            </Alert>\n          )\n        }",
  "alert:Custom colors": "const Demo = () => (\n          <div className=\"grid w-full max-w-md gap-4\">\n            <Alert className=\"border-emerald-500/30 bg-emerald-500/10 text-emerald-700 dark:text-emerald-400\">\n              <CheckCircleIcon />\n              <AlertTitle>Success</AlertTitle>\n              <AlertDescription className=\"text-emerald-700/80 dark:text-emerald-400/80\">\n                Your changes have been saved successfully.\n              </AlertDescription>\n            </Alert>\n            <Alert className=\"border-amber-500/30 bg-amber-500/10 text-amber-700 dark:text-amber-400\">\n              <TriangleAlertIcon />\n              <AlertTitle>Warning</AlertTitle>\n              <AlertDescription className=\"text-amber-700/80 dark:text-amber-400/80\">\n                Your storage is almost full. Consider upgrading your plan.\n              </AlertDescription>\n            </Alert>\n          </div>\n        )",
  "aspect-ratio:Portrait": "const Demo = () => (\n          <div className=\"w-full max-w-48\">\n            <AspectRatio ratio=\"portrait\" className=\"bg-muted rounded-lg\">\n              <img\n                src=\"https://images.unsplash.com/photo-1588345921523-c2dcdb7f1dcd?w=400&dpr=2&q=80\"\n                alt=\"Portrait photo\"\n                className=\"h-full w-full rounded-lg object-cover\"\n              />\n            </AspectRatio>\n          </div>\n        )",
