  "attachment:Group": "const Demo = () => (\n          <AttachmentGroup className=\"max-w-md\">\n            {[\"report.pdf\", \"design.fig\", \"notes.md\", \"data.csv\"].map(\n              (name) => (\n                <Attachment key={name} size=\"sm\">\n                  <AttachmentMedia variant=\"icon\">\n                    <FileIcon aria-hidden />\n                  </AttachmentMedia>\n                  <AttachmentContent>\n                    <AttachmentTitle>{name}</AttachmentTitle>\n                    <AttachmentDescription>1 MB</AttachmentDescription>\n                  </AttachmentContent>\n                </Attachment>\n              )\n            )}\n          </AttachmentGroup>\n        )",
  "attachment:Image": "const Demo = () => (\n          <Attachment className=\"w-72\">\n            <AttachmentMedia variant=\"image\">\n              <img\n                src=\"https://picsum.photos/seed/attach/80/80\"\n                alt=\"Photo preview\"\n              />\n            </AttachmentMedia>\n            <AttachmentContent>\n              <AttachmentTitle>vacation-photo.jpg</AttachmentTitle>\n              <AttachmentDescription>1.8 MB</AttachmentDescription>\n            </AttachmentContent>\n            <AttachmentActions>\n              <AttachmentAction aria-label=\"Remove image\">\n                <XIcon aria-hidden />\n              </AttachmentAction>\n            </AttachmentActions>\n          </Attachment>\n        )",
  "attachment:Sizes": "const Demo = () => (\n          <div className=\"flex flex-col gap-3\">\n            {([\"default\", \"sm\", \"xs\"] as const).map((size) => (\n              <Attachment key={size} size={size} className=\"w-56\">\n                <AttachmentMedia variant=\"icon\">\n                  <FileIcon aria-hidden />\n                </AttachmentMedia>\n                <AttachmentContent>\n                  <AttachmentTitle>{size} size</AttachmentTitle>\n                  <AttachmentDescription>1.2 MB</AttachmentDescription>\n                </AttachmentContent>\n                <AttachmentActions>\n                  <AttachmentAction aria-label={`Remove ${size}`}>\n                    <XIcon aria-hidden />\n                  </AttachmentAction>\n                </AttachmentActions>\n              </Attachment>\n            ))}\n          </div>\n        )",
  "attachment:States": "function StatesDemo() {\n          const [states, setStates] = useState<\n            Record<string, \"idle\" | \"uploading\" | \"processing\" | \"error\" | \"done\">\n          >({\n            idle: \"idle\",\n            uploading: \"uploading\",\n            processing: \"processing\",\n            error: \"error\",\n            done: \"done\",\n          })\n          return (\n            <div className=\"flex flex-wrap gap-3\">\n              {(\n                Object.entries(states) as [\n                  string,\n                  \"idle\" | \"uploading\" | \"processing\" | \"error\" | \"done\",\n                ][]\n              ).map(([key, state]) => (\n                <Attachment key={key} state={state} className=\"w-56\">\n                  <AttachmentMedia variant=\"icon\">\n                    {state === \"error\" ? (\n                      <AlertCircleIcon aria-hidden />\n                    ) : (\n                      <FileIcon aria-hidden />\n                    )}\n                  </AttachmentMedia>\n                  <AttachmentContent>\n                    <AttachmentTitle>\n                      {state === \"uploading\"\n                        ? \"Uploading…\"\n                        : state === \"processing\"\n                          ? \"Processing…\"\n                          : `file-${key}.pdf`}\n                    </AttachmentTitle>\n                    <AttachmentDescription>\n                      {state === \"error\" ? \"Upload failed\" : \"2.4 MB\"}\n                    </AttachmentDescription>\n                  </AttachmentContent>\n                  <AttachmentActions>\n                    {state === \"error\" ? (\n                      <AttachmentAction\n                        aria-label=\"Retry upload\"\n                        onClick={() =>\n                          setStates((s) => ({ ...s, [key]: \"uploading\" }))\n                        }\n                      >\n                        <RotateCwIcon aria-hidden />\n                      </AttachmentAction>\n                    ) : (\n                      <AttachmentAction\n                        aria-label=\"Remove\"\n                        onClick={() =>\n                          setStates((s) => ({ ...s, [key]: \"idle\" }))\n                        }\n                      >\n                        <XIcon aria-hidden />\n                      </AttachmentAction>\n                    )}\n                  </AttachmentActions>\n                </Attachment>\n              ))}\n            </div>\n          )\n        }",
  "attachment:Trigger": "function TriggerDemo() {\n          const inputRef = useRef<HTMLInputElement>(null)\n          const [fileName, setFileName] = useState<string | null>(null)\n          return (\n            <div className=\"flex flex-col gap-3\">\n              <input\n                ref={inputRef}\n                type=\"file\"\n                className=\"sr-only\"\n                aria-label=\"Select file\"\n                onChange={(e) => {\n                  const f = e.target.files?.[0]\n                  if (f) setFileName(f.name)\n                }}\n              />\n              <Attachment\n                state=\"idle\"\n                className=\"w-72 cursor-pointer\"\n                onClick={() => inputRef.current?.click()}\n              >\n                <AttachmentMedia variant=\"icon\">\n                  <PaperclipIcon aria-hidden />\n                </AttachmentMedia>\n                <AttachmentContent>\n                  <AttachmentTitle>\n                    {fileName ?? \"Choose a file\"}\n                  </AttachmentTitle>\n                  <AttachmentDescription>\n                    {fileName ? \"Selected\" : \"Click to browse\"}\n                  </AttachmentDescription>\n                </AttachmentContent>\n                <AttachmentTrigger aria-label=\"Choose file\" />\n              </Attachment>\n            </div>\n          )\n        }",
